#include <bits/stdc++.h>
using namespace std;
int main(){
    int cases; cin>>cases;
    for(int c=0;c<cases;c++){
        int n; cin>>n;
        vector<int> w(n);
        int total=0;
        for(int i=0;i<n;i++){ cin>>w[i]; total+=w[i]; }
        vector<bitset<45001>> dp(n+1);
        dp[0][0]=1;
        for(int idx=0; idx<n; idx++){
            for(int i=min(idx,n-1); i>=0; i--){
                dp[i+1] |= dp[i] << w[idx];
            }
        }
        int k1 = n/2;
        int bestDiff=INT_MAX, bestS=-1;
        for(int j=0;j<=total;j++){
            if(dp[k1][j]){
                int diff = abs(total-2*j);
                if(diff<bestDiff){ bestDiff=diff; bestS=j; }
            }
        }
        int a=bestS, b=total-bestS;
        if(a>b) swap(a,b);
        if (c) cout << "\n";
        cout << a << " " << b << "\n";
    }
}

